+func compactContextEntries(entries []ContextEntry, max int) []ContextEntry {
+	out := []ContextEntry{}
+	seen := map[string]bool{}
+	for i := len(entries) - 1; i >= 0; i-- {
+		entry := entries[i]
+		if isNoisyRunContext(entry.Content) {
+			continue
+		}
+		key := entry.Kind + "\x00" + strings.TrimSpace(entry.Content)
+		if seen[key] {
