	case "set-token":
		if len(args) < 2 {
			return fmt.Errorf("usage: taskpilot config set-token <token>")
		}
		cfg.Token = args[1]
	case "set-api-key":
		if len(args) < 2 {
			return fmt.Errorf("usage: taskpilot config set-api-key <key>")
		}
		cfg.APIKey = args[1]
	case "set-actor":
